import type { Data } from 'plotly.js-dist-min'

// Static data files generated by `curation/airport_winds/convert_to_json.py`
export const AIRPORT_WINDS_DATA_PATH = '/data/airport-winds/'

export const DEFAULT_AIRPORT = 'PAFA'

export type WindSpeedUnits = 'kts' | 'mph' | 'm/s'
export type PetalCount = '8' | '16' | '36'

export interface AirportRunway {
  name: string
  heading: number
}

export interface AirportStation {
  sid: string
  label: string
  name: string
  lat: number
  lng: number
  startYear: number
  runways: AirportRunway[]
}

// Rose frequencies (%), indexed [speed range][direction], with directions
// running clockwise from north.
export type RoseFrequencies = number[][]

export interface AirportWindsData {
  sid: string
  // Keyed by petal count, then indexed by month (0 = all months).
  roses: Record<PetalCount, RoseFrequencies[]>
  // Percent calm, indexed by month (0 = all months).
  calms: number[]
  // Oldest available decade and 2010-2019, or null if insufficient data.
  comparison: {
    decades: string[]
    roses: Record<PetalCount, RoseFrequencies[]>
    calms: number[]
  } | null
  exceedance: {
    directions: number[]
    thresholds: {
      threshold: number
      rdcClass: string
      exceedance: number[]
    }[]
  }
  wep: {
    month: number[]
    year: number[]
    wep: number[]
  }
}

