export const SPEED_RANGE_LABELS: Record<WindSpeedUnits, string[]> = {
  mph: ['0-6', '6-10', '10-14', '14-18', '18-22', '22+'],
  kts: ['0-5.2', '5.2-8.7', '8.7-12.2', '12.2-15.7', '15.7-19.1', '19.1+'],
  'm/s': ['0-2.7', '2.7-4.5', '4.5-6.3', '6.3-8', '8-9.8', '9.8+'],
}

