export const stationTitle = (station: AirportStation): string =>
  `${station.name} (${station.sid}), ${station.startYear}–present`

// Wind direction in degrees for each petal, clockwise from north.
const petalDirections = (petalCount: number): number[] =>
  Array.from({ length: petalCount }, (_, i) => (i * 360) / petalCount)

// One trace per speed range. Bars stack into petals by default. With
// `lines`, each speed range is drawn as a closed line instead, which is used
// to show differences between roses.
export const getRoseTraces = (
  rose: RoseFrequencies,
  units: WindSpeedUnits,
  options: { showLegend?: boolean; lines?: boolean; subplot?: string } = {}
): Data[] => {
  return rose.map((frequencies, i) => {
    const name = `${SPEED_RANGE_LABELS[units][i]} ${units}`
    const theta = petalDirections(frequencies.length)
    const trace: Record<string, any> = {
      r: [...frequencies],
      theta,
      name,
      marker: { color: SPEED_COLORS[i] },
      showlegend: options.showLegend ?? false,
      legendgroup: 'speed',
      hovertemplate: `%{r}% ${name} winds from %{theta}°<extra></extra>`,
      subplot: options.subplot ?? 'polar',
    }
    if (options.lines) {
      trace.type = 'scatterpolar'
      trace.mode = 'lines'
      trace.line = { color: SPEED_COLORS[i] }
      trace.r.push(frequencies[0])
      trace.theta = [...theta, theta[0]]
      trace.hovertemplate = `%{r:.2f}% change in ${name}<br>winds from %{theta}°<extra></extra>`
    } else {
      trace.type = 'barpolar'
    }
    return trace as Data
  })
}

// Maximum extent of any petal on the rose, summed across speed ranges.
export const maxPetal = (rose: RoseFrequencies): number => {
  return Math.max(
    ...rose[0].map((_, direction) =>
      rose.reduce((sum, speedRange) => sum + speedRange[direction], 0)
    )
  )
}

// Calm annotation text, with the "calm" label only if there's room for it.
export const calmText = (percent: number): string => {
  let text = Math.round(percent) + '%'
  if (percent > 20) {
    text += ' calm'
  }
  return text
}

export const purgeChart = (chartId: string) => {
  const { $Plotly } = useNuxtApp()
  try {
    const element = document.getElementById(chartId)
    if (element && element.hasChildNodes()) {
      $Plotly.purge(chartId)
    }
  } catch (error) {
    // Ignore purge errors - chart may already be cleaned up
    console.debug(`Chart purge skipped for ${chartId}:`, error)
  }
}
